"""Half-open integer interval utilities."""


def _clean(intervals):
    return [(int(s), int(e)) for s, e in intervals if s < e]


def merge(intervals) -> list[tuple[int, int]]:
    pairs = sorted(_clean(intervals))
    out: list[tuple[int, int]] = []
    for start, end in pairs:
        if out and start <= out[-1][1]:
            if end > out[-1][1]:
                out[-1] = (out[-1][0], end)
        else:
            out.append((start, end))
    return out


def free_gaps(intervals, window) -> list[tuple[int, int]]:
    ws, we = int(window[0]), int(window[1])
    if ws >= we:
        return []
    clipped = []
    for s, e in _clean(intervals):
        cs, ce = max(s, ws), min(e, we)
        if cs < ce:
            clipped.append((cs, ce))
    merged = merge(clipped)
    gaps: list[tuple[int, int]] = []
    cursor = ws
    for s, e in merged:
        if cursor < s:
            gaps.append((cursor, s))
        cursor = e
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals) -> int:
    events = []
    for s, e in _clean(intervals):
        events.append((s, 1))
        events.append((e, -1))
    # at equal points, ends (closures) are processed before starts
    events.sort(key=lambda ev: (ev[0], -ev[1]))
    depth = best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._clock = clock
        # key -> (value, expires_at or None); ordered LRU -> MRU
        self._entries = OrderedDict()

    @staticmethod
    def _is_expired(expires_at, now):
        return expires_at is not None and now >= expires_at

    def _purge_expired(self):
        now = self._clock()
        expired = [
            key
            for key, (_, expires_at) in self._entries.items()
            if self._is_expired(expires_at, now)
        ]
        for key in expired:
            del self._entries[key]
        return len(expired)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        expires_at = None if ttl is None else self._clock() + ttl
        if key in self._entries:
            self._entries[key] = (value, expires_at)
            self._entries.move_to_end(key)
            return
        if len(self._entries) >= self._capacity:
            self._purge_expired()
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        self._entries[key] = (value, expires_at)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        value, expires_at = entry
        if self._is_expired(expires_at, self._clock()):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return False
        return not self._is_expired(entry[1], self._clock())

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator (tokenizer + recursive-descent parser).

Precedence, lowest to highest: + -  <  * / // %  <  unary - +  <  **
** is right-associative; the other binary operators are left-associative.
"""


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            if j < n and text[j] == "." and j + 1 < n and text[j + 1].isdigit():
                j += 1
                while j < n and text[j].isdigit():
                    j += 1
                tokens.append(("num", float(text[i:j])))
            else:
                tokens.append(("num", int(text[i:j])))
            i = j
            continue
        if ch == "." and i + 1 < n and text[i + 1].isdigit():
            j = i + 1
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(("num", float(text[i:j])))
            i = j
            continue
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(("name", text[i:j]))
            i = j
            continue
        if text.startswith("//", i):
            tokens.append(("op", "//"))
            i += 2
            continue
        if text.startswith("**", i):
            tokens.append(("op", "**"))
            i += 2
            continue
        if ch in "+-*/%":
            tokens.append(("op", ch))
            i += 1
            continue
        if ch == "(":
            tokens.append(("lp", ch))
            i += 1
            continue
        if ch == ")":
            tokens.append(("rp", ch))
            i += 1
            continue
        if ch == ",":
            tokens.append(("comma", ch))
            i += 1
            continue
        raise ValueError("unknown character %r" % ch)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self._toks = tokens
        self._i = 0

    def _peek(self):
        return self._toks[self._i] if self._i < len(self._toks) else None

    def _next(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        self._i += 1
        return tok

    def _parse_additive(self):
        value = self._parse_multiplicative()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] in ("+", "-"):
                self._i += 1
                rhs = self._parse_multiplicative()
                value = value + rhs if tok[1] == "+" else value - rhs
            else:
                return value

    def _parse_multiplicative(self):
        value = self._parse_unary()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] in ("*", "/", "//", "%"):
                self._i += 1
                rhs = self._parse_unary()
                if tok[1] == "*":
                    value = value * rhs
                elif tok[1] == "/":
                    value = value / rhs
                elif tok[1] == "//":
                    value = value // rhs
                else:
                    value = value % rhs
            else:
                return value

    def _parse_unary(self):
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] in ("+", "-"):
            self._i += 1
            operand = self._parse_unary()
            return operand if tok[1] == "+" else -operand
        return self._parse_power()

    def _parse_power(self):
        base = self._parse_primary()
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "**":
            self._i += 1
            exponent = self._parse_unary()
            return base ** exponent
        return base

    def _parse_primary(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("expected an operand")
        kind, val = tok
        if kind == "num":
            self._i += 1
            return val
        if kind == "lp":
            self._i += 1
            value = self._parse_additive()
            close = self._next()
            if close[0] != "rp":
                raise ValueError("expected ')'")
            return value
        if kind == "name":
            self._i += 1
            return self._parse_call(val)
        raise ValueError("unexpected token %r" % val)

    def _parse_call(self, name):
        open_t = self._next()
        if open_t[0] != "lp":
            raise ValueError("expected '(' after function name %r" % name)
        if name not in ("min", "max", "abs"):
            raise ValueError("unknown function %r" % name)
        args = [self._parse_additive()]
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "comma":
                self._i += 1
                args.append(self._parse_additive())
            else:
                break
        close = self._next()
        if close[0] != "rp":
            raise ValueError("expected ')'")
        if name == "abs":
            if len(args) != 1:
                raise ValueError("abs takes exactly one argument")
            return abs(args[0])
        return min(args) if name == "min" else max(args)


def evaluate(text: str):
    tokens = _tokenize(text)
    if not tokens:
        raise ValueError("empty expression")
    parser = _Parser(tokens)
    result = parser._parse_additive()
    leftover = parser._peek()
    if leftover is not None:
        raise ValueError("unexpected token %r" % leftover[1])
    return result
